/// Lesson sections for the info page — never shown on the practice screen.
const List<TechniqueSection> setFillTripletsLesson = [
  TechniqueSection(
    title: "Why it matters",
    body:
        "In a shuffle only a triplet fill fits, and on the kit the triplets roll down the toms in the same lilt as the hi-hat. This is the pad sheet \"Triplet Fill\" with the shuffle groove around it.",
  ),
  TechniqueSection(
    title: "How to play it",
    body:
        "Three bars of shuffle: the hi-hat plays the first and last note of each triplet, snare on 2 and 4, kick on 1 and 3; bar 1 opens with the crash. In line 1 the fill plays two beats of triplets on the snare, beat 3 on the high tom and beat 4 on the floor tom, one triplet per drum, while the kick keeps 1 and 3.",
  ),
  TechniqueSection(
    title: "Practice tips",
    body:
        "Line 4 is R L L twice on the high tom and twice on the floor tom: the right hand leads every drum change. Line 5 plays the dotted shuffle on the snare and ends with one triplet on the floor tom. Line 7 travels all four toms with a rest at the start of beats 2 and 4, line 8 plays doubles inside the triplets, snare, high tom, floor tom and back to the snare. Count \"1 trip let\" until the fill swings like the hat. Toms accept any tom and the crash any crash, so a kit with fewer drums plays the sheet too: the mid tom and the second floor tom go to the nearest tom you have.",
  ),
  TechniqueSection(
    title: "Where you hear it",
    body:
        "Blues shuffles, slow 12/8 ballads and every triplet tom fill in a swung rock song.",
  ),
];
